total = len(ARCHITECTURES)
ids = [a["id"] for a in ARCHITECTURES]
if len(ids) != len(set(ids)):
    raise ValueError(f"Duplicate IDs found! Total: {len(ids)}, Unique: {len(set(ids))}")

for a in ARCHITECTURES:
    if a.get("support_status") not in VALID_SUPPORT_STATUSES:
        raise ValueError(f"Invalid or missing support_status for {a['id']}")

tested = [a["id"] for a in ARCHITECTURES if a["support_status"] == "tested"]
experimental = [a["id"] for a in ARCHITECTURES if a["support_status"] == "experimental"]

out_path = Path(__file__).resolve().parent.parent / "registry" / "model_architectures.json"
with open(out_path, "w", encoding="utf-8") as f:
    json.dump({
        "schema_version": "1.3.0",
        "runtime_version": "0.3.1",
        "total_count": total,
        "tested_count": len(tested),
        "experimental_count": len(experimental),
        "supported_families_count": len(set(a["family"] for a in ARCHITECTURES)),
        "architectures": ARCHITECTURES
    }, f, indent=2, ensure_ascii=False)
    f.write("\n")

print(f"Generated {out_path}: {total} architectures ({len(tested)} tested, {len(experimental)} experimental).")
